<script>
window.waitForWelcomeAnimation=panel=>{
    if(!panel||panel.classList.contains('animation-started'))return Promise.resolve();
    return new Promise(resolve=>{
        const observer=new IntersectionObserver(entries=>{
            if(!entries.some(entry=>entry.isIntersecting&&entry.intersectionRatio>=.18))return;
            observer.disconnect();
            panel.classList.add('animation-started');
            resolve();
        },{threshold:[.18],rootMargin:'0px 0px -5% 0px'});
        observer.observe(panel);
    });
};
