<script>document.addEventListener('DOMContentLoaded',()=>{const technology=document.querySelector('#how');if(!technology)return;const section=document.createElement('section');section.className='home-section';section.id='entry-exit';section.innerHTML=`<div class="home-wrap"><div class="entry-exit-panel"><div class="entry-exit-grid"><div class="entry-exit-copy"><div class="kicker">EINSTIEG &amp; AUSSTIEG</div><h2>Mehrere Zeiträume.<br><span class="grad">Mehr Kontrolle.</span></h2><p>Prediction-Marker zeigen mögliche Einstiegszeitpunkte über verschiedene Prognosehorizonte. Dazu vergleichst du mehrere Exit-Strategien und wählst den Ansatz, der zu deinem Risiko und Anlageziel passt.</p><div class="strategy-list"><div class="strategy-item"><span class="strategy-icon">△</span><span><b>Mehrere Einstiegszeiträume</b><br>5, 10, 15 und 20 Tage im direkten Vergleich</span></div><div class="strategy-item"><span class="strategy-icon">↗</span><span><b>Mehrere Exit-Strategien</b><br>Take-Profit, Stop-Loss und dynamischer Ausstieg</span></div><div class="strategy-item"><span class="strategy-icon">◎</span><span><b>Passend zu deinem Profil</b><br>Chancen und Risiken bleiben jederzeit sichtbar</span></div></div></div><div class="prediction-chart"><div class="exit-tags"><span>TAKE PROFIT</span><span>STOP LOSS</span><span>DYNAMISCH</span></div><svg viewBox="0 0 700 250" preserveAspectRatio="none"><defs><linearGradient id="predictionArea" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#52f1ff" stop-opacity=".22"/><stop offset="1" stop-color="#52f1ff" stop-opacity="0"/></linearGradient></defs><path class="prediction-area" d="M0 213 C45 200 70 218 110 186 S175 180 215 193 S278 144 325 158 S380 112 430 126 S488 82 535 96 S604 48 700 34 L700 250 L0 250Z"/><path class="prediction-average" d="M0 205 C120 196 220 184 325 157 S510 106 700 54"/><path class="prediction-price" d="M0 213 C45 200 70 218 110 186 S175 180 215 193 S278 144 325 158 S380 112 430 126 S488 82 535 96 S604 48 700 34"/><g class="prediction-marker m1" transform="translate(325 158)"><polygon points="0,-12 -8,2 8,2"/><text x="12" y="0">5T</text></g><g class="prediction-marker m2" transform="translate(430 126)"><polygon points="0,-12 -8,2 8,2"/><text x="12" y="0">10T</text></g><g class="prediction-marker m3" transform="translate(535 96)"><polygon points="0,-12 -8,2 8,2"/><text x="12" y="0">15T</text></g><g class="prediction-marker m4" transform="translate(650 47)"><polygon points="0,-12 -8,2 8,2"/><text x="12" y="0">20T</text></g></svg><div class="chart-horizons"><div class="chart-horizon"><small>5 TAGE</small><b>+1,8 %</b></div><div class="chart-horizon"><small>10 TAGE</small><b>+3,2 %</b></div><div class="chart-horizon"><small>15 TAGE</small><b>+5,1 %</b></div><div class="chart-horizon"><small>20 TAGE</small><b>+7,4 %</b></div></div></div></div></div></div>`;technology.before(section)});</script>
<script>
