    ]);
    const translations = new Map(pairs.map(([de, en]) => locale === 'en' ? [de.toLocaleUpperCase('de-DE'), en] : [en.toLocaleUpperCase('en-US'), de]));
    const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
    const nodes = [];
    while (walker.nextNode()) nodes.push(walker.currentNode);
    nodes.forEach(node => {
        const value = node.nodeValue.trim();
        const translated = translations.get(value.toLocaleUpperCase(locale === 'en' ? 'de-DE' : 'en-US'));
        if (translated) node.nodeValue = node.nodeValue.replace(value, translated);
    });
