<script>
document.addEventListener('DOMContentLoaded',()=>{document.querySelectorAll('.market-panel').forEach(panel=>{const stage=panel.querySelector('.market-chart .chart-stage');let started=false;const replay=()=>{if(started)return;started=true;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;panel.querySelectorAll('.donut[data-value]').forEach((donut,index)=>{const circle=donut.querySelector('.donut-value'),output=donut.querySelector('.donut-number'),target=Number(donut.dataset.value),suffix=donut.dataset.suffix||'';donut.classList.remove('active');delete donut.dataset.animated;circle.style.transition='none';circle.style.strokeDashoffset='251.3';output.textContent='0'+suffix;void circle.getBoundingClientRect();setTimeout(()=>{requestAnimationFrame(()=>{circle.style.removeProperty('transition');circle.style.removeProperty('stroke-dashoffset');donut.classList.add('active')});if(reduced){output.textContent=(target%1?target.toFixed(2):Math.round(target))+suffix;return}const start=performance.now(),duration=1500;const tick=now=>{const progress=Math.min((now-start)/duration,1),value=target*(1-Math.pow(1-progress,3));output.textContent=(target%1?value.toFixed(2):Math.round(value))+suffix;if(progress<1)requestAnimationFrame(tick)};requestAnimationFrame(tick)},index*180)})};if(stage)stage.addEventListener('animationstart',event=>{if(event.animationName==='referenceChartRevealForward'||event.animationName==='referenceChartReveal')replay()},{once:true});window.waitForWelcomeAnimation(panel).then(()=>setTimeout(replay,19100))})});
</script>
<script>
