<script>
document.addEventListener('DOMContentLoaded',()=>{document.querySelectorAll('.market-panel').forEach(panel=>{const stage=panel.querySelector('.market-chart .chart-stage'),donuts=[...panel.querySelectorAll('.donut[data-value]')];if(!stage||!donuts.length)return;donuts.forEach(donut=>{donut.dataset.pendingValue=donut.dataset.value;delete donut.dataset.value;delete donut.dataset.animated;donut.classList.remove('active');const circle=donut.querySelector('.donut-value'),output=donut.querySelector('.donut-number');circle.style.transition='none';circle.style.strokeDashoffset='251.3';output.textContent='0'+(donut.dataset.suffix||'')});let completed=false;const fillDonuts=()=>{if(completed)return;completed=true;donuts.forEach((donut,index)=>setTimeout(()=>{const target=Number(donut.dataset.pendingValue),suffix=donut.dataset.suffix||'',circle=donut.querySelector('.donut-value'),output=donut.querySelector('.donut-number');donut.dataset.value=String(target);circle.style.removeProperty('transition');circle.style.removeProperty('stroke-dashoffset');void circle.getBoundingClientRect();requestAnimationFrame(()=>donut.classList.add('active'));const start=performance.now(),duration=1500,tick=now=>{const progress=Math.min((now-start)/duration,1),value=target*(1-Math.pow(1-progress,3));output.textContent=(target%1?value.toFixed(2):Math.round(value))+suffix;if(progress<1)requestAnimationFrame(tick)};requestAnimationFrame(tick)},index*180))};stage.addEventListener('animationend',event=>{if(event.animationName==='referenceChartRevealForward'||event.animationName==='referenceChartReveal')fillDonuts()},{once:true});window.waitForWelcomeAnimation(panel).then(()=>setTimeout(fillDonuts,22000))})});
</script>
